function fakeFetch(shouldFail) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (shouldFail) reject(new Error('Server is down'));
      else resolve({ name: 'Ada Lovelace', role: 'Engineer' });
    }, 800);
  });
}

function App() {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const load = (shouldFail) => {
    setLoading(true); setError(null); setData(null);
    fakeFetch(shouldFail)
      .then(setData)
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  };
  useEffect(() => { load(false); }, []);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={() => load(false)}>Reload</button>
      <button onClick={() => load(true)} style={{ marginLeft: 8 }}>Reload (fail)</button>
      <div style={{ marginTop: 12 }}>
        {loading && <p>Loading...</p>}
        {error && <p style={{ color: 'crimson' }}>Error: {error}</p>}
        {data && <p>{data.name} - {data.role}</p>}
      </div>
    </div>
  );
}

function fakeFetch(id) {
  // smaller ids are slower, so an earlier request can resolve last
  const delay = id === 1 ? 1200 : 300;
  return new Promise((res) => setTimeout(() => res('Result for id ' + id), delay));
}

function App() {
