function fakeFetch() {
  return new Promise((res) => setTimeout(() => res({ msg: 'Hello from server' }), 700));
}

function useFetch(asyncFn) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  useEffect(() => {
    let ignored = false;
    setLoading(true); setError(null);
    asyncFn()
      .then((d) => { if (!ignored) { setData(d); setLoading(false); } })
      .catch((e) => { if (!ignored) { setError(e); setLoading(false); } });
    return () => { ignored = true; };
  }, [asyncFn]);
  return { data, loading, error };
}

function App() {
  const { data, loading, error } = useFetch(fakeFetch);
