function fakeSearch(q) {
  const delay = q.length <= 2 ? 1000 : 200;
  return new Promise((res) => setTimeout(() => res('Results for: ' + q), delay));
}

function App() {
  const [q, setQ] = useState('');
  const [results, setResults] = useState('');
  useEffect(() => {
    let ignored = false;
    fakeSearch(q).then((r) => { if (!ignored) setResults(r); });
    return () => { ignored = true; }; // drop stale responses
  }, [q]);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="search" />
      <p>{results}</p>
    </div>
